{
  "description": "LayerFS workspaces for every agent in magpie: deduplicated checkpoints and branches behind stable filesystem paths, instead of a fresh copy of the tree for every agent, with a page that replays the worktree trajectory",
  "exports": {
    ".": "./index.mjs"
  },
  "files": [
    "index.mjs",
    "layerfs.mjs",
    "page-service.mjs",
    "page",
    "README.md",
    "icon.svg"
  ],
  "keywords": [
    "magpie",
    "magpie-tools",
    "mcp",
    "opencode",
    "opencode-plugin",
    "layerfs",
    "filesystem",
    "workspace",
    "checkpoint",
    "dedup"
  ],
  "license": "MIT",
  "magpie": {
    "icon": "data:image/svg+xml;base64,",
    "options": {
      "exec": false,
      "pagePort": 43717
    },
    "page": {
      "file": "page/index.html",
      "icon": "page/icon.svg",
      "service": {
        "port": 43717,
        "option": "pagePort"
      },
      "title": "LayerFS trajectory",
      "titles": {
        "ja": "LayerFS の軌跡",
        "zh": "LayerFS 轨迹",
        "zh-TW": "LayerFS 軌跡"
      }
    }
  },
  "main": "./index.mjs",
  "name": "@jianmu-plugins/tools-layerfs",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/magpie-community/plugins.git",
    "directory": "packages/layerfs"
  },
  "type": "module",
  "version": "0.10.3"
}

// LayerFS for every agent magpie connects: instead of each agent copying a
// project tree to work on it, agents share one durable, deduplicated history
// and work through stable workspace paths. Forking a branch for a parallel
// agent copies no file bytes; a checkpoint stores only what changed.
// Arguments are JSON Schema, so the package needs no dependency.
//
// The page's data channel: the plugin host's own localhost-only service
// (page-service.mjs). A magpie page cannot fetch and cannot read
// plugin-private files, so the installed page/index.html only navigates
// its frame to the service, which embeds backend.trajectory() — the
// page's real commits, branches, storage and dedup accounting, with the
// real calling agent on each — in the HTML it returns. With no store
// it serves the empty state; see the README's page section.
//
// Backend: a local content-addressed store with the LayerFS model, in
// layerfs.mjs. The native backend (the real LayerFS SDK) is not shipped
// in this registry package — the SDK is still not published to npm —
// and returns once the plugin can pin it as a dependency. See the README.
import { readdirSync } from "node:fs"
import { join } from "node:path"
import { checkBranch, checkInnerPath, checkProject, checkSourceDir, createBackend, storeHome } from "./layerfs.mjs"
import { resolvePagePort, startPageService } from "./page-service.mjs"

const str = (v, name) => {
  if (typeof v !== "string" || !v) throw new Error(`${name} is a non-empty string`)
  return v
}
const opt = (v, name, dflt) => (v === undefined || v === "" ? dflt : str(v, name))

// The calling agent, as the gateway knows it (the tool host's ctx.agent):
// the one field of a tool call that says WHO made it. Trimmed and capped,
// then recorded on the events and commits the call creates — the page
// attributes the work to the agent that actually made it, not to a token
// guessed from the branch name.
const callingAgent = (ctx) => {
  const a = ctx?.agent
  return typeof a === "string" && a.trim() ? a.trim().slice(0, 40) : ""
}

// ---- the page's live channel: the host's own service ---------------------
// The service starts once per plugin instance, at load, store or no
// store: the installed page jumps its frame to it, and a WebKit frame
// whose jump is refused keeps showing "Connecting…" for good (0.10.1 and
// before started it only once a store existed). With no store it serves
// the page's empty state and builds no backend, so nothing is written
// under ~ until a tool call makes the first project. The start is off
// the tool calls' path and every failure is swallowed: a held port or a
// failed read leaves the tools untouched.

export const LayerfsTools = async (ctx = {}, options = {}) => {
  let backendPromise
  const backend = () => (backendPromise ??= createBackend(process.env, options).catch((error) => {
    backendPromise = undefined
    throw error
  }))
  const execEnabled = () => options?.exec === true || process.env.MAGPIE_LAYERFS_EXEC === "1"
  // A call touches only the state its own operation needs. Reads (history,
  // resolve, status) change nothing and start nothing.
  const call = async (fn) => {
    const b = await backend()
    return fn(b)
  }
  // A new host may start before the retired host releases this port.
  // Keep one start in flight, and remember a service only after it
  // actually listens. Retry with backoff, without keeping an otherwise
  // finished host alive.
  let service = null
  let starting = null
  let retryTimer = null
  let retryDelay = 1000
  const retry = () => {
    if (retryTimer || service?.server.listening) return
    retryTimer = setTimeout(() => {
      retryTimer = null
      ensureService().catch(() => { /* the page never blocks a tool */ })
    }, retryDelay)
    retryTimer.unref?.()
    retryDelay = Math.min(retryDelay * 2, 30000)
  }
  // What the service serves: the store's trajectory once a store exists,
  // else an empty recording, so the page shows its empty state (and
  // reloads itself into the first project) instead of a frame that never
  // lands. The store is looked for without building the backend: its
  // constructor is what creates the store's folders, and a user with no
  // store gets nothing written.
  const empty = () => ({ projects: [], events: [], generatedAt: new Date().toISOString() })
  const pageBackend = {
    trajectory: async () => {
      try {
        if (!readdirSync(join(storeHome(), "projects")).length) return empty()
      } catch {
        return empty()
      }
      return (await backend()).trajectory()
    },
  }
  const ensureService = () => {
    if (service?.server.listening) return Promise.resolve()
    if (starting) return starting
    if (retryTimer) {
      clearTimeout(retryTimer)
      retryTimer = null
    }
    starting = (async () => {
      const candidate = startPageService({ backend: pageBackend, port: resolvePagePort(options) })
      const stopped = () => {
        if (service !== candidate || candidate.server.listening) return
        service = null
        retry()
      }
      candidate.server.once("close", stopped)
      candidate.server.on("error", stopped)
      if (!await candidate.listening || !candidate.server.listening) {
        retry()
        return
      }
      service = candidate
      retryDelay = 1000
    })().catch(() => {
      retry()
    }).finally(() => {
      starting = null
    })
    return starting
  }
  ensureService().catch(() => { /* no service: the tools are untouched */ })
  // A mutating call: the service, up since load, reads the store it
  // writes on the page's next reload.
  const mutate = call

  return {
    tool: {
      provision: {
        description:
          "Gives the agent a LayerFS workspace for a project branch and answers the filesystem path to work in. " +
          "The first provision of a project imports the source directory the caller passes — source is required, there is no default — as its first checkpoint; " +
          "later provisions of the same branch answer the same path without copying the tree again (source is then ignored). " +
          "Pass the directory the user chose for this project: the app's config directory, credential stores (.ssh, .aws, .gnupg), the home directory and the plugin's own store are refused as sources, " +
          "and secret-shaped files in the tree (.env*, private keys, .git internals) never enter the store — the sim backend skips them on import and reports how many. " +
          "Work in the returned path, then save progress with the checkpoint tool. " +
          "Only the returned path is persistent — work anywhere else, including the host's /tmp, is outside LayerFS management; " +
          "the workspace also carries .tmp/ and .cache/ scratch directories (exec points TMPDIR and XDG_CACHE_HOME at them), which checkpoint and publish never capture.",
        args: {
          type: "object",
          properties: {
            project: { type: "string", description: "LayerFS project name, e.g. website" },
            branch: { type: "string", description: "branch to work on (default main)" },
            source: { type: "string", description: "the directory the user chose for this project; imported when the project is first created, ignored afterwards" },
          },
          required: ["project", "source"],
        },
        async execute(args, callCtx) {
          const project = checkProject(str(args.project, "project"))
          const branch = checkBranch(opt(args.branch, "branch", "main"))
          // ctx.directory is magpie's config directory, never a default
          // source: it holds plugin credentials. It is refused as a
          // source here (and in the backend) like the other blocked roots.
          if (args.source === undefined) throw new Error(
            "source is required: the directory to import when the project is first created — pass the directory the user chose for this project")
          const source = checkSourceDir(str(args.source, "source"), { configDir: ctx.directory })
          return mutate((b) => b.provision(project, branch, source, callingAgent(callCtx)))
        },
      },
      checkpoint: {
        description:
          "Saves the workspace's current state as a deduplicated checkpoint on its branch: only blobs the store has not seen are written. " +
          "The real cost model: the changed blobs, plus one commit record per checkpoint holding the tree's full manifest — " +
          "for a wide tree the manifests are a real part of the store's bytes, and the storage accounting counts them. " +
          "Answers the commit id and the added / modified / deleted counts with the new-bytes and saved-bytes accounting.",
        args: {
          type: "object",
          properties: {
            project: { type: "string", description: "LayerFS project name" },
            branch: { type: "string", description: "branch the workspace belongs to (default main)" },
            message: { type: "string", description: "what this checkpoint did" },
          },
          required: ["project"],
        },
        async execute(args, callCtx) {
          const project = checkProject(str(args.project, "project"))
          const branch = checkBranch(opt(args.branch, "branch", "main"))
          return mutate((b) => b.checkpoint(project, branch, opt(args.message, "message", ""), callingAgent(callCtx)))
        },
      },
      fork: {
        description:
          "Forks a branch of a project for a parallel agent. A fork is a pointer at an existing checkpoint: it copies no file bytes and is ready immediately, " +
          "where copying the tree for another agent costs the whole tree's size and time. Provision the new branch to get its workspace path.",
        args: {
          type: "object",
          properties: {
            project: { type: "string", description: "LayerFS project name" },
            branch: { type: "string", description: "the new branch's name" },
            from: { type: "string", description: "branch to fork from (default main)" },
          },
          required: ["project", "branch"],
        },
        async execute(args, callCtx) {
          const project = checkProject(str(args.project, "project"))
          const branch = checkBranch(str(args.branch, "branch"))
          const from = checkBranch(opt(args.from, "from", "main"))
          return mutate((b) => b.fork(project, branch, from, callingAgent(callCtx)))
        },
      },
      publish: {
        description:
          "Publishes a branch's head as main's new state (a Layer), so the work every agent did on that branch becomes what new work forks from. " +
          "Guarded: main's current head must be in the branch's history, so a publish can only move main forward; if main has newer checkpoints the branch never saw, " +
          "the publish is refused and says so. Pass force: true only to overwrite deliberately; the result then reports overwrote and the previous main head.",
        args: {
          type: "object",
          properties: {
            project: { type: "string", description: "LayerFS project name" },
            branch: { type: "string", description: "branch to publish to main" },
            force: { type: "boolean", description: "overwrite main even if it has checkpoints the branch never saw (default false)" },
          },
          required: ["project", "branch"],
        },
        async execute(args, callCtx) {
          const project = checkProject(str(args.project, "project"))
          const branch = checkBranch(str(args.branch, "branch"))
          return mutate((b) => b.publish(project, branch, { force: args.force === true, agent: callingAgent(callCtx) }))
        },
      },
      exec: {
        description:
          "Runs a shell command inside a branch's provisioned workspace and checkpoints whatever it changed as one commit: run, test, fix, all captured in the branch's history. " +
          "DISABLED by default: the command runs with the plugin host's privileges, and the host serves these tools to remote callers holding a gateway key, so a shell is not something a model key should silently become. " +
          "It runs only when the user has opted in — the plugin's \"exec\" option set to true, or the exec switch in the host's environment. " +
          "A command that changes nothing commits nothing. A failing command's changes are still checkpointed (history can be rewound), and its exit code, stdout and stderr are returned. " +
          "Only the workspace path is persistent: the command runs with TMPDIR and XDG_CACHE_HOME redirected into the workspace (.tmp/ and .cache/), " +
          "workspace-local scratch that checkpoint and publish never capture, and files written to the host's real /tmp are likewise outside LayerFS management. " +
          "The timeout is capped at 55 seconds, the tools budget.",
        args: {
          type: "object",
          properties: {
            project: { type: "string", description: "LayerFS project name" },
            branch: { type: "string", description: "branch whose workspace to run in (default main)" },
            command: { type: "string", description: "the shell command to run in the workspace" },
            message: { type: "string", description: "checkpoint message (default: the command itself)" },
            timeoutMs: { type: "number", description: "timeout in milliseconds (default 50000, capped at 55000)" },
          },
          required: ["project", "command"],
        },
        async execute(args, callCtx) {
          if (!execEnabled()) throw new Error(
            "layerfs_exec is disabled by default: it runs shell commands with the plugin host's privileges, and these tools are reachable by any caller holding a gateway key. " +
            "To enable it, the user sets the plugin's \"exec\" option to true in the host's plugin options, or turns on the exec switch in the plugin host's environment (see the package's README), and restarts the host.")
          const project = checkProject(str(args.project, "project"))
          const branch = checkBranch(opt(args.branch, "branch", "main"))
          const command = str(args.command, "command")
          const message = args.message === undefined ? "" : str(args.message, "message")
          const timeoutMs = args.timeoutMs === undefined ? 50000 : Number(args.timeoutMs) || 50000
          return mutate((b) => b.exec(project, branch, command, message, timeoutMs, callingAgent(callCtx)))
        },
      },
      history: {
        description:
          "Lists a branch's checkpoints, newest first: commit id, message, time, file count and the logical size of the tree at that point, " +
          "plus how many new bytes that checkpoint actually stored. The history is shared and durable: any agent can read what every other agent committed.",
        args: {
          type: "object",
          properties: {
            project: { type: "string", description: "LayerFS project name" },
            branch: { type: "string", description: "branch to read (default main)" },
            limit: { type: "number", description: "how many checkpoints to return (default 20)" },
          },
          required: ["project"],
        },
        async execute(args) {
          const project = checkProject(str(args.project, "project"))
          const branch = checkBranch(opt(args.branch, "branch", "main"))
          const limit = args.limit === undefined ? 20 : Math.max(1, Math.min(200, Number(args.limit) || 20))
          return call((b) => b.history(project, branch, limit))
        },
      },
      resolve: {
        description:
          "Resolves a logical LayerFS location to a real filesystem path without copying anything: the workspace path for a project branch, " +
          "or one file inside it, with the checkpoint that path currently answers for and, for a file, its content hash and size. " +
          "Use it to find where a branch lives before reading or handing the path to another tool.",
        args: {
          type: "object",
          properties: {
            project: { type: "string", description: "LayerFS project name" },
            branch: { type: "string", description: "branch to resolve (default main)" },
            path: { type: "string", description: "a file path inside the workspace, relative to its root" },
          },
          required: ["project"],
        },
        async execute(args) {
          const project = checkProject(str(args.project, "project"))
          const branch = checkBranch(opt(args.branch, "branch", "main"))
          const inner = args.path === undefined || args.path === "" ? "" : checkInnerPath(str(args.path, "path"))
          return call((b) => b.resolve(project, branch, inner))
        },
      },
      status: {
        description:
          "Reports the LayerFS backend in use, the projects and branches it holds, and the storage accounting: " +
          "the logical bytes of every checkpoint ever taken against the bytes the deduplicated store actually occupies, and the ratio between them.",
        args: { type: "object", properties: {} },
        async execute() {
          return call((b) => b.status())
        },
      },
    },
  }
}

// The trajectory page, drawn the way LayerFS's own History picture is:
// main is the green middle bough, every other branch a bough that splits
// off it, a checkpoint a badge on its bough bearing its agent's own
// icon (the marks magpie itself ships for them), and a publish a graft
// back onto main that lands a Layer badge. The replay is one continuous
// timeline, driven by requestAnimationFrame through the pure motion
// model in view.js: boughs draw themselves as the playhead passes,
// badges land with a pulse while their icons draw themselves, and the
// counters count up along the same easing magpie itself uses
// (--ease, cubic-bezier(.2,.8,.2,1)).
//
// The data is the trajectory the host service embedded in this page
// (<script type="application/json" id="data">): the service reads it
// from the store on every request, so a reload is always current. A
// page opened without the service — the bundled sample defining
// globalThis.LayerfsTrajectory — still works from that global. A
// magpie page cannot read plugin-private data: the bridge's reads are
// a fixed host list (usage:summary, providers:list), and the sandbox
// allows no fetch, so the service, not a file, is the channel.
(async () => {
  const V = globalThis.LayerfsView;
  const $ = (id) => document.getElementById(id);
  const SVG = "http://www.w3.org/2000/svg";
  const RM = matchMedia("(prefers-reduced-motion: reduce)").matches;
  const STEP_MS = 560; // one checkpoint's stretch of timeline at 1×
  const PULSE_MS = 650;

  let theme = { lang: "en", dark: matchMedia("(prefers-color-scheme: dark)").matches };
  // The service hands the language over as LayerfsTheme (the served
  // page is outside magpie, so magpie.ready is not there to ask); a
  // page still inside magpie asks magpie.ready as before.
  const preset = globalThis.LayerfsTheme
  if (preset && typeof preset.lang === "string" && preset.lang) theme.lang = preset.lang
  else try { theme = (await magpie.ready) || theme; } catch { /* standalone preview */ }
  const lang = theme.lang || "en";
  const t = V.text(lang);
  document.querySelectorAll("[data-t]").forEach((e) => { e.textContent = t[e.dataset.t]; });

  // branch colours: an agent's branch wears the agent's own brand
  // colour in both themes; the rest take magpie's chart series, and
  // main is the leaf green (deeper on light, brighter on dark)
  const SERIES = {
    dark: ["#a5b4fc", "#7dd3fc", "#6ee7b7", "#fcd34d", "#f9a8d4", "#c4b5fd", "#94a3b8"],
    light: ["#4f46e5", "#0ea5e9", "#10b981", "#f59e0b", "#ec4899", "#8b5cf6", "#64748b"],
  };
  const series = () => SERIES[theme.dark ? "dark" : "light"];
  const mainColor = () => (theme.dark ? "#4ade80" : "#16a34a");
  const colorOf = (branch, lane) =>
    (V.agentOf(branch) || {}).color ||
    (lane === 0 ? mainColor() : series()[(lane - 1) % series().length]);

  // The embedded recording first; the bundled sample's global second.
  const embedded = document.getElementById("data");
  let data = null;
  if (embedded) {
    try { data = JSON.parse(embedded.textContent); } catch { /* a broken embed shows the empty state */ }
  }
  if (!data) data = globalThis.LayerfsTrajectory;
  const projects = (data && data.projects || []).filter((p) => p.branches.some((b) => b.commits.length));
  if (!projects.length) {
    $("stage").hidden = true; $("controls").hidden = true; $("stats").hidden = true; $("agents").hidden = true;
    $("empty").hidden = false; $("empty").textContent = t.noData;
    // the service's empty answer reloads too, so the first provision
    // shows up without the reader reopening the page
    if (embedded) setTimeout(() => location.reload(), 5000);
    return;
  }
  $("stamp").textContent = data.sample ? t.sample : `${t.recorded} ${String(data.generatedAt || "").replace("T", " ").slice(0, 19)} · ${data.backend || ""}`;

  // Agent activity: every recorded tool call, newest last, each naming
  // the calling agent, the tool, the project, the branch and when. The
  // events arrive in the service's embedded trajectory; with none
  // recorded the table gives way to an empty note.
  {
    const events = (data.events || []).slice(-40);
    const section = $("agents"), rows = $("agentRows"), emptyMsg = $("agentsEmpty");
    section.hidden = false;
    if (!events.length) {
      $("agentTable").hidden = true;
      emptyMsg.hidden = false;
      emptyMsg.textContent = t.agentsEmpty;
    } else {
      $("agentTable").hidden = false;
      emptyMsg.hidden = true;
      for (const e of events) {
        const tr = document.createElement("tr");
        const cells = [
          e.agent || "—", e.kind || "—", e.project || "—", e.branch || "—",
          String(e.t || "").replace("T", " ").slice(0, 19),
        ];
        for (const c of cells) {
          const td = document.createElement("td");
          td.textContent = c;
          tr.append(td);
        }
        rows.append(tr);
      }
    }
  }

  // the project picker: a magpie-style menu (a button and a listbox),
  // not a native <select> — magpie's own UI never uses one
  let currentProject = projects[0].name;
  const menu = $("projectMenu"), projBtn = $("projBtn"), projList = $("projList");
  for (const p of projects) {
    const b = document.createElement("button");
    b.type = "button";
    b.setAttribute("role", "option");
    b.dataset.project = p.name;
    b.textContent = p.name;
    projList.append(b);
  }
  menu.hidden = projects.length < 2;
  function paintMenu() {
    projBtn.textContent = currentProject;
    projList.querySelectorAll("button").forEach((b) =>
      b.setAttribute("aria-selected", String(b.dataset.project === currentProject)));
  }
  function setMenuOpen(open) {
    projList.hidden = !open;
    projBtn.setAttribute("aria-expanded", String(open));
  }
  projBtn.addEventListener("click", (e) => {
    e.stopPropagation();
    setMenuOpen(projList.hidden);
  });
  projList.addEventListener("click", (e) => {
    const b = e.target.closest("button[data-project]");
    if (!b) return;
    setMenuOpen(false);
    if (b.dataset.project !== currentProject) show(b.dataset.project);
  });
  document.addEventListener("click", () => setMenuOpen(false));

  function el(name, attrs = {}, parent) {
    const e = document.createElementNS(SVG, name);
    for (const [k, v] of Object.entries(attrs)) e.setAttribute(k, v);
    if (parent) parent.append(e);
    return e;
  }
  const seg = (a, b) => {
    const mx = (a.x + b.x) / 2;
    return `M ${a.x} ${a.y} C ${mx} ${a.y}, ${mx} ${b.y}, ${b.x} ${b.y}`;
  };

  // the live picture: element registries keyed by replay step, rebuilt
  // per project; render() then only moves styles and attributes
  let view = null; // { project, L, stepsList, nodes, segs, grafts, bands, badges }
  let playhead = 0, playing = false, speed = 1, focus = null, pinned = false;
  let lastLanded = -1, raf = 0, lastTs = 0;
  const pulses = new Map(); // step -> pulse start (performance.now)
  const shown = {}; // last strings written to the stat tiles

  function build(name) {
    stop(); focus = null; pinned = false; pulses.clear(); lastLanded = -1;
    const project = projects.find((p) => p.name === name) || projects[0];
    const stepsList = V.steps(project);
    const wide = Math.max(320, ($("stage").clientWidth || 720) - 8);
    // never squish below a readable pitch: the stage scrolls instead
    const dx = stepsList.length > 1 ? Math.max(46, Math.min(76, (wide - 68) / (stepsList.length - 1))) : 54;
    const L = V.layout(project, data.events, { dx, laneH: 56, padTop: 46 });
    view = { project, L, stepsList, nodes: [], segs: [], grafts: [], bands: [], badges: [] };
    $("histLine").textContent = `${t.history} ${project.name} @ L${L.topLayer}`;
    $("histMeta").textContent = `${L.nodes.length} commits · ${L.laneCount} ${t.live} · ${L.topLayer + 1} ${t.layers}`;
    const svg = $("graph");
    svg.replaceChildren();
    svg.removeAttribute("data-focus");
    svg.setAttribute("viewBox", `0 0 ${L.width} ${L.height}`);
    svg.setAttribute("width", L.width); svg.setAttribute("height", L.height);
    const all = [...L.nodes, ...L.landings];
    const mainY = (L.spines.get("main") || [])[0]?.y ?? 46;

    // Layer bands on main: a stratum behind the bough per layer,
    // fading in as its layer begins
    L.bands.forEach((band, i) => {
      const g = el("g", { class: "band" }, svg);
      el("rect", {
        x: band.x0 - 16, y: mainY - 18, width: Math.max(30, band.x1 - band.x0 + 32), height: 36, rx: 18,
        class: "band-fill",
      }, g);
      const label = el("text", { y: mainY - 28, class: "band-label" }, g);
      // the band a head publish just opened has no width yet: anchor its
      // label at the publish point instead of past the edge
      if (i === L.bands.length - 1 && band.x1 - band.x0 < 60) {
        label.setAttribute("x", band.x1 + 14); label.setAttribute("text-anchor", "end");
      } else {
        label.setAttribute("x", band.x0 - 6);
      }
      label.textContent = `L${band.layer}`;
      view.bands.push({ g, start: i === 0 ? 0 : L.grafts[i - 1].to.step });
    });
    // grafts under everything: a publish joining a branch back to main,
    // drawn as the playhead reaches it; a Layer badge pops at its head
    for (const gr of L.grafts) {
      const path = el("path", {
        d: seg(gr.from, gr.to), class: "graft", pathLength: 1,
        "data-branch": gr.from.branch, stroke: colorOf(gr.from.branch, gr.from.lane),
      }, svg);
      view.grafts.push({ path, step: gr.to.step, branch: gr.from.branch });
      const badge = el("g", { class: "badge", transform: `translate(${gr.to.x} ${mainY - 36})` }, svg);
      const pop = el("g", { class: "badge-pop" }, badge);
      const label = `L${gr.layer}`;
      el("rect", { x: -13 - (label.length - 2) * 3.5, y: -8, width: 26 + (label.length - 2) * 7, height: 16, rx: 8, class: "badge-fill" }, pop);
      const txt = el("text", { y: 3.5, class: "badge-text" }, pop);
      txt.textContent = label;
      view.badges.push({ g: badge, pop, step: gr.to.step, branch: gr.from.branch });
    }
    // one group per branch: spine segments that draw themselves as
    // their target checkpoint appears
    for (const [branch, pts] of L.spines) {
      const g = el("g", { class: "lane", "data-branch": branch }, svg);
      const laneIdx = L.laneOf(branch);
      for (let i = 1; i < pts.length; i++) {
        const a = pts[i - 1], b = pts[i];
        const path = el("path", {
          d: seg(a, b), class: "seg" + (a.lane !== b.lane ? " split-seg" : ""), pathLength: 1,
          stroke: colorOf(branch, laneIdx), "data-branch": branch,
        }, g);
        view.segs.push({ path, step: b.step });
      }
    }
    // checkpoints: a positioned group (attribute transform) around an
    // animated group (style transform), so the two never fight; the
    // loose ring is the landing pulse. The badge itself is a soft disc
    // in the branch's colour, ringed in it, and its face is the icon
    // of the agent that owns the branch — drawn in the ink that reads
    // on that colour — or the agent's monogram when it has no glyph,
    // or LayerFS's leaf when the bough names no agent at all
    for (const n of all) {
      const g = el("g", { class: "lane", "data-branch": n.branch }, svg);
      const pos = el("g", { transform: `translate(${n.x} ${n.y})` }, g);
      const color = colorOf(n.branch, n.lane);
      const ring = el("circle", {
        r: 13, class: "ring", fill: "none",
        stroke: color, "stroke-width": 2, opacity: 0,
      }, pos);
      const anim = el("g", { class: "node" + (n.landing ? " landing" : ""), "data-branch": n.branch }, pos);
      el("circle", { r: 12.5, class: "badge-disc", fill: color }, anim);
      el("circle", { r: 12.5, class: "badge-ring", fill: "none", stroke: color }, anim);
      const face = V.glyphFor(n.branch, n.commit);
      const ink = V.markInk(color);
      const glyphPaths = [];
      let glyphMark = null;
      if (face.type === "mark") {
        glyphMark = el("text", { y: 3.4, class: "glyph-mark", fill: ink }, anim);
        glyphMark.textContent = face.agent.mark;
      } else {
        const glyph = face.type === "icon" ? face.icon : face.glyph;
        const inner = el("svg", {
          x: -8, y: -8, width: 16, height: 16, viewBox: glyph.viewBox, class: "glyph",
        }, anim);
        for (const p of glyph.paths) {
          const attrs = {
            d: p.d, class: "glyph-path", pathLength: 1,
            fill: ink, stroke: ink, "stroke-width": glyph.sw || 1.3,
          };
          if (p.rule) attrs["fill-rule"] = p.rule;
          glyphPaths.push(el("path", attrs, inner));
        }
      }
      anim.addEventListener("click", () => { pinned = true; pause(); select(n); });
      view.nodes.push({ anim, ring, step: n.step, node: n, glyphPaths, glyphMark });
    }
    // name tags at each branch's first own leaf; main needs none — the
    // HISTORY line and the Layer bands name it. An agent's branch gets
    // its monogram chip in the agent's colour, like magpie's own rows.
    for (const b of project.branches) {
      if (b.name === "main") continue;
      const first = L.nodes.find((n) => n.branch === b.name);
      if (!first) continue;
      const g = el("g", { class: "lane", "data-branch": b.name }, svg);
      const tag = el("g", { class: "tag", transform: `translate(${first.x - 4} ${first.y - 30})` }, g);
      const agent = V.agentOf(b.name);
      let nameX = 0;
      if (agent) {
        el("rect", { x: -2, y: -11, width: 23, height: 15, rx: 3.5, fill: agent.color, class: "chip" }, tag);
        const mark = el("text", { x: 9.5, y: 1, class: "chip-mark", fill: V.markInk(agent.color) }, tag);
        mark.textContent = agent.mark;
        nameX = 27;
      }
      const label = el("text", { x: nameX, y: 1, class: "tag-label", fill: colorOf(b.name, first.lane) }, tag);
      label.textContent = b.name + (!L.graftedBranches.has(b.name) ? " ·" : "");
      tag.addEventListener("click", () => setFocus(focus === b.name ? null : b.name));
    }
    // legend: which agents are in this picture, in their own colours
    const legend = $("legend");
    legend.replaceChildren();
    const seen = new Map();
    for (const b of project.branches) {
      const a = V.agentOf(b.name);
      if (a && !seen.has(a.id)) seen.set(a.id, a);
    }
    for (const a of seen.values()) {
      const item = document.createElement("span");
      item.className = "legend-item";
      const icon = V.ICONS[a.id];
      if (icon) {
        const mini = el("svg", { width: 14, height: 14, viewBox: icon.viewBox, class: "legend-icon" });
        for (const p of icon.paths) {
          const attrs = { d: p.d, fill: a.color };
          if (p.rule) attrs["fill-rule"] = p.rule;
          el("path", attrs, mini);
        }
        item.append(mini);
      } else {
        const dot = document.createElement("i");
        dot.style.background = a.color;
        item.append(dot);
      }
      item.append(document.createTextNode(a.name));
      legend.append(item);
    }
    legend.hidden = seen.size === 0;
    for (const k of Object.keys(shown)) delete shown[k];
  }

  function setFocus(branch) {
    focus = branch;
    const svg = $("graph");
    if (!branch) { svg.removeAttribute("data-focus"); return; }
    svg.setAttribute("data-focus", branch);
    document.querySelectorAll("#graph .lane, #graph .graft").forEach((e) => {
      e.classList.toggle("focus", e.dataset.branch === branch);
    });
  }

  function setText(id, value) {
    if (shown[id] === value) return;
    shown[id] = value;
    $(id).textContent = value;
  }

  // one frame of the replay at the current playhead
  function render() {
    if (!view) return;
    const { L, stepsList } = view;
    const n = stepsList.length;
    const f = V.frame(stepsList, playhead);
    for (const s of view.segs) {
      const p = f.progress[s.step];
      s.path.style.strokeDashoffset = String(1 - p);
      s.path.style.opacity = p > 0 ? "" : "0";
    }
    for (const g of view.grafts) {
      const p = f.progress[g.step];
      g.path.style.strokeDashoffset = String(1 - p);
      g.path.style.opacity = p > 0 ? (focus && focus !== g.branch ? "0.13" : "") : "0";
    }
    for (const b of view.bands) {
      b.g.style.opacity = String(V.magpieEase(V.clamp01(playhead - b.start)));
    }
    for (const b of view.badges) {
      const raw = V.clamp01(playhead - b.step);
      b.g.style.opacity = raw > 0 ? (focus && focus !== b.branch ? "0.25" : "1") : "0";
      b.pop.style.transform = `scale(${Math.max(0.0001, V.easeOutBack(raw))})`;
    }
    for (const nd of view.nodes) {
      const p = f.progress[nd.step];
      nd.anim.style.opacity = String(p);
      nd.anim.style.transform = `scale(${0.35 + 0.65 * p}) rotate(${-14 * (1 - p)}deg)`;
      nd.anim.classList.toggle("sel", !!nd.node._sel);
      // as the badge lands, its icon draws itself and then its fill
      // fades in; under reduced motion the icon is simply there,
      // fully drawn at any point of the scrub
      const d = V.iconDraw(p, RM);
      for (const gp of nd.glyphPaths) {
        gp.style.strokeDashoffset = String(d.offset);
        gp.style.fillOpacity = String(d.fillOpacity);
        gp.style.strokeOpacity = String(d.strokeOpacity);
      }
      if (nd.glyphMark) nd.glyphMark.style.opacity = String(d.fillOpacity);
    }
    // the counters count up along the same frame
    const total = stepsList[n - 1];
    setText("nCommits", `${f.landed} / ${n}`);
    setText("tBranches", String(f.branches));
    setText("vCopies", V.bytes(f.logical));
    setText("vStored", V.bytes(f.stored));
    setText("tDedup", f.stored > 0 ? `${(f.logical / f.stored).toFixed(2)}×` : "–");
    setText("vSaved", f.logical > 0 ? `${t.saved} ${V.bytes(f.logical - f.stored)} (${Math.round((1 - f.stored / f.logical) * 100)}%)` : "");
    $("barCopies").style.width = total && total.cumLogical ? `${Math.max(1.5, (f.logical / total.cumLogical) * 100)}%` : "0%";
    $("barStored").style.width = total && total.cumLogical ? `${Math.max(1.5, (f.stored / total.cumLogical) * 100)}%` : "0%";
    if (document.activeElement !== $("scrub")) $("scrub").value = n ? Math.round((playhead / n) * 1000) : 0;
    // landing bookkeeping: pulses only for steps the playhead crosses
    // while playing — a scrub sets the state without fanfare
    if (playing && !RM) {
      for (let s = Math.max(0, lastLanded); s < f.landed; s++) pulses.set(s, performance.now());
    }
    if (f.landed !== lastLanded) {
      lastLanded = f.landed;
      if (!pinned) {
        if (f.landed > 0) select(L.nodes[f.landed - 1]);
        else clearDetail();
      }
    }
  }

  function renderPulses(now) {
    for (const [step, start] of pulses) {
      const s = V.pulse((now - start) / PULSE_MS);
      for (const nd of view.nodes) {
        if (nd.step !== step) continue;
        if (!s) { nd.ring.setAttribute("opacity", 0); continue; }
        nd.ring.setAttribute("r", (nd.node.landing ? 17 : 13) * s.scale);
        nd.ring.setAttribute("opacity", s.opacity);
      }
      if (!s) pulses.delete(step);
    }
  }

  function loop(ts) {
    raf = 0;
    if (playing) {
      if (lastTs) {
        playhead = Math.min(view.stepsList.length, playhead + ((ts - lastTs) / STEP_MS) * speed);
        if (playhead >= view.stepsList.length) pause();
      }
      lastTs = ts;
    } else {
      lastTs = 0;
    }
    render();
    renderPulses(ts);
    if (playing || pulses.size) raf = requestAnimationFrame(loop);
  }
  function ensureLoop() { if (!raf) { lastTs = 0; raf = requestAnimationFrame(loop); } }

  function play() {
    if (!view || playing) return;
    pinned = false;
    if (playhead >= view.stepsList.length) { playhead = 0; lastLanded = -1; pulses.clear(); }
    if (RM) { playhead = view.stepsList.length; render(); return; }
    playing = true;
    $("play").textContent = t.pause;
    ensureLoop();
  }
  function pause() {
    playing = false;
    $("play").textContent = t.replay;
  }
  function stop() { pause(); if (raf) cancelAnimationFrame(raf); raf = 0; }

  function select(node) {
    const d = V.detail(node.commit, lang);
    const graft = view.L.grafts.find((g) => g.to === node);
    $("dBranch").textContent = `${t.branch}: ${node.branch}` +
      (graft ? ` · ${t.graft} L${graft.layer}` : node.branch !== "main" && isTip(node) && !view.L.graftedBranches.has(node.branch) ? ` · ${t.twig}` : "");
    $("dMsg").textContent = d.message;
    $("dMeta").textContent = [d.agent, d.meta].filter(Boolean).join(" · ");
    $("dDelta").textContent = d.delta;
    $("dTime").textContent = String(node.commit.time || "").replace("T", " ").slice(0, 19);
    $("dDot").style.background = colorOf(node.branch, node.lane);
    for (const nd of view.nodes) nd.node._sel = nd.node === node;
    for (const nd of view.nodes) nd.anim.classList.toggle("sel", nd.node === node);
  }
  function clearDetail() {
    $("dBranch").textContent = ""; $("dMsg").textContent = "";
    $("dMeta").textContent = ""; $("dDelta").textContent = ""; $("dTime").textContent = "";
    $("dDot").style.background = "transparent";
    for (const nd of view.nodes) { nd.node._sel = false; nd.anim.classList.remove("sel"); }
  }
  function isTip(node) {
    return !view.L.nodes.some((n) => n.branch === node.branch && n.step > node.step);
  }

  function show(name, keep = false) {
    const at = playhead;
    currentProject = name;
    paintMenu();
    build(name);
    const n = view.stepsList.length;
    // reduced motion, or a theme change mid-look: settle on the final
    // state (clamped to the new picture) instead of replaying
    playhead = keep ? Math.min(at, n) : RM ? n : 0;
    render();
    if (!RM && !keep && n) play();
  }

  $("play").addEventListener("click", () => (playing ? pause() : play()));
  $("scrub").addEventListener("input", () => {
    pause(); pinned = false; pulses.clear();
    playhead = view ? (Number($("scrub").value) / 1000) * view.stepsList.length : 0;
    lastLanded = -1; // render re-derives the detail for the new position
    render();
  });
  $("speed").addEventListener("click", (e) => {
    const b = e.target.closest("button[data-speed]");
    if (!b) return;
    speed = Number(b.dataset.speed);
    for (const x of $("speed").querySelectorAll("button")) {
      if (x === b) x.setAttribute("aria-selected", "true"); else x.removeAttribute("aria-selected");
    }
  });
  if (window.magpie && typeof magpie.onTheme === "function") {
    magpie.onTheme((th) => {
      const dark = !!th.dark;
      if (dark === theme.dark) return;
      theme = { ...theme, dark };
      show(currentProject, true);
    });
  }

  // the store.stats line, in LayerFS's own accounting words
  const totals = data.totals || {};
  $("statsLine").textContent =
    `${t.stats} · ${t.dedupe} ${totals.dedupRatio ?? "–"}× · ${t.stored} ${V.bytes(totals.storedBytes)} / ${V.bytes(totals.logicalBytes)}`;

  // A reload restores the view the old document left in location.hash
  // (see view.js): the project, the scroll, and the replay position —
  // paused, not replayed. Without a hash this is a plain first look
  // and the replay runs.
  const restored = V.resolveRestoredView(projects, location.hash, RM);
  show(restored ? restored.project : projects[0].name, !!restored);
  if (restored) {
    playhead = (restored.settled || RM) ? view.stepsList.length : restored.playhead;
    render();
    if (restored.scrollY) window.scrollTo(0, restored.scrollY);
  }

  // Liveness: the page reloads itself every few seconds so the picture
  // stays current — but never in the middle of a look. While the
  // replay runs or the project menu stands open the tick waits and
  // tries again; otherwise it writes the view into the hash first, so
  // the fresh document restores exactly this look instead of starting
  // over at the first project, the top, and the replay's beginning.
  // A reload-only-when-changed tick is not possible in the frame: the
  // sandbox allows no fetch, so the page cannot learn whether the
  // trajectory moved without reloading — and the service must not
  // answer cross-origin reads. The hash is the whole channel.
  function armReload() { setTimeout(reloadTick, 5000); }
  function reloadTick() {
    if (playing || !projList.hidden) { armReload(); return; }
    location.hash = V.formatViewHash({
      project: currentProject,
      scrollY: Math.round(window.scrollY || 0),
      playhead,
    });
    location.reload();
  }
  armReload();
})();
